75	      language: SupportedLanguage.TYPESCRIPT,
76	      destination: RN_STORYBOOK_DIR,
77	      features: context.features,
78	    });
79	
80	    const templateVariant: ReactNativeEntrypointTemplateVariant =
81	      detectReactNativeEntrypointTemplateVariant(packageManager.getAllDependencies());
