2	import path, { dirname, join } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	
5	import { RN_STORYBOOK_DIR } from '../../../../../core/src/shared/constants/config-folder.ts';
6	import { SupportedLanguage } from 'storybook/internal/types';
7	
8	const ENTRYPOINT_TEMPLATE_DIR = join(
9	  dirname(fileURLToPath(import.meta.resolve('create-storybook/package.json'))),
10	  'templates',
11	  'react-native'
12	);
13	
14	export type ReactNativeEntrypointTemplateVariant = 'default' | 'expo';
15	
16	export const getEntrypointExtension = (language: SupportedLanguage) => {
17	  return language === SupportedLanguage.TYPESCRIPT ? 'ts' : 'js';
18	};
19	
20	export const getEntrypointTemplatePath = (
21	  templateVariant: ReactNativeEntrypointTemplateVariant = 'default'
22	) => {
23	  const templateFileName = templateVariant === 'expo' ? 'index.expo.js' : 'index.js';
24	  return join(ENTRYPOINT_TEMPLATE_DIR, templateFileName);
25	};
26	
27	export const generateReactNativeEntrypoint = async ({
28	  language,
29	  templateVariant = 'default',
30	  cwd = process.cwd(),
31	}: {
32	  language: SupportedLanguage;
33	  templateVariant?: ReactNativeEntrypointTemplateVariant;
34	  cwd?: string;
35	}) => {
36	  const extension = getEntrypointExtension(language);
37	  const templatePath = getEntrypointTemplatePath(templateVariant);
38	  const targetDir = path.join(cwd, RN_STORYBOOK_DIR);
39	  const targetPath = path.join(targetDir, `index.${extension}`);
40	
41	  const templateContents = await readFile(templatePath, 'utf-8');
42	
43	  await mkdir(targetDir, { recursive: true });
44	  await writeFile(targetPath, templateContents, 'utf-8');
45	
46	  return {
47	    targetPath,
48	    extension,
49	  };
50	};
